{"implementation": "import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")

    payload = case.get("payload", case)
    if not isinstance(payload, dict):
        raise ValueError("payload must be an object")

    required = ("nodes", "core_distance", "distances")
    for key in required:
        if key not in payload:
            raise ValueError("missing required field: " + key)

    nodes = payload["nodes"]
    core_in = payload["core_distance"]
    distances = payload["distances"]

    if not isinstance(nodes, list):
        raise ValueError("nodes must be a list")
    if not isinstance(core_in, dict):
        raise ValueError("core_distance must be an object")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    seen_nodes = set()
    node_order = {}
    for i, node in enumerate(nodes):
        if not isinstance(node, str) or node == "":
            raise ValueError("node identifiers must be non-empty strings")
        if node in seen_nodes:
            raise ValueError("duplicate node identifier")
        seen_nodes.add(node)
        node_order[node] = i

    def valid_number(value, name):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError(name + " must be numeric")
        value = float(value)
        if not math.isfinite(value):
            raise ValueError(name + " must be finite")
        if value < 0.0:
            raise ValueError(name + " must be non-negative")
        return value

    if set(core_in.keys()) != seen_nodes:
        raise ValueError("core_distance keys must match nodes exactly")

    core_distance = {}
    for node in nodes:
        core_distance[node] = valid_number(core_in[node], "core_distance")

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        root = node
        while parent[root] != root:
            root = parent[root]
        while parent[node] != node:
            next_node = parent[node]
            parent[node] = root
            node = next_node
        return root

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return False
        if rank[left_root] < rank[right_root]:
            parent[left_root] = right_root
        elif rank[left_root] > rank[right_root]:
            parent[right_root] = left_root
        else:
            parent[right_root] = left_root
            rank[left_root] += 1
        return True

    pair_seen = set()
    mutual_edges = []

    for position, entry in enumerate(distances):
        if not isinstance(entry, (list, tuple)) or len(entry) != 3:
            raise ValueError("each distance entry must have three values")
        raw_left, raw_right, raw_distance = entry
        if not isinstance(raw_left, str) or not isinstance(raw_right, str):
            raise ValueError("distance endpoints must be strings")
        if raw_left not in seen_nodes or raw_right not in seen_nodes:
            raise ValueError("distance endpoint not present in nodes")
        if raw_left == raw_right:
            raise ValueError("self distances are not valid MST edges")

        if raw_left <= raw_right:
            left, right = raw_left, raw_right
        else:
            left, right = raw_right, raw_left
        pair = (left, right)
        if pair in pair_seen:
            raise ValueError("duplicate undirected distance pair")
        pair_seen.add(pair)

        distance = valid_number(raw_distance, "distance")
        core_left = core_distance[left]
        core_right = core_distance[right]
        reachability = max(core_left, core_right, distance)

        mutual_edges.append({
            "left": left,
            "right": right,
            "source_left": raw_left,
            "source_right": raw_right,
            "source_position": position,
            "distance": distance,
            "core_left": core_left,
            "core_right": core_right,
            "mutual_reachability": reachability,
        })

    sorted_edges = sorted(
        mutual_edges,
        key=lambda edge: (edge["mutual_reachability"], edge["left"], edge["right"]),
    )

    mst_edges = []
    target_count = max(0, len(nodes) - 1)
    for edge in sorted_edges:
        if union(edge["left"], edge["right"]):
            mst_edges.append(dict(edge))
            if len(mst_edges) == target_count:
                break

    if len(mst_edges) != target_count:
        raise ValueError("distance graph is disconnected")

    total_weight = sum(edge["mutual_reachability"] for edge in mst_edges)

    return {
        "nodes": list(nodes),
        "core_distance": {node: core_distance[node] for node in nodes},
        "mutual_reachability_edges": sorted_edges,
        "mst_edges": mst_edges,
        "total_weight": total_weight,
    }
"}
